public Mappings diffStructure(String tableName, Mappings mappings) {

    // Check if the input mappings are null or empty
    if (mappings == null || mappings.isEmpty()) {
        throw new IllegalArgumentException("Input mappings cannot be null or empty");
    }

    // Check if the table name is null or empty
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }

    // Get the current index mappings
    Mappings currentMappings = getCurrentMappings(tableName);

    // Check if the current index mappings are null or empty
    if (currentMappings == null || currentMappings.isEmpty()) {
        throw new IllegalStateException("Current index mappings cannot be null or empty");
    }

    // Create a new mappings object to store the diff
    Mappings diffMappings = new Mappings();

    // Iterate over the input mappings and compare with the current index mappings
    for (Mapping mapping : mappings) {
        // Check if the mapping exists in the current index mappings
        if (!currentMappings.contains(mapping)) {
            // If the mapping does not exist, add it to the diff mappings
            diffMappings.add(mapping);
        }
    }

    // Return the diff mappings
    return diffMappings;
}

