private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the suffix sum list and the sum of all elements
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // Iterate over the bounds list and compute the suffix sum
    for (int i = 0; i < bounds.size(); i++) {
        int bound = bounds.get(i);
        sum += bound;
        suffixSum.add(sum);
    }

    // Return the computed suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Invalid input");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("List cannot be null");
    }
    if (list.isEmpty()) {
        return;
    }
    ListNode<E> currentNode = list.getHead();
    while (currentNode != null) {
        ListNode<E> nextNode = currentNode.getNext();
        removeListNode(currentNode);
        addListNode(currentNode);
        currentNode = nextNode;
    }
}

