private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }

    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph contains all the vertices in the set
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Check if the graph is connected
    if (!isConnected(graph)) {
        return false;
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Step 1: Sort the keys in ascending order
    Collections.sort(keys);

    // Step 2: Initialize the lower bounds list with the first key
    List<Integer> lowerBounds = new ArrayList<>();
    lowerBounds.add(keys.get(0));

    // Step 3: Iterate over the remaining keys and update the lower bounds
    for (int i = 1; i < keys.size(); i++) {
        int currentKey = keys.get(i);
        int previousKey = keys.get(i - 1);
        int lowerBound = Math.max(previousKey, currentKey);
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}

private void pop(final String descriptor) {
    // Step 1: Parse the descriptor to determine the number of types to pop
    int numTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            numTypes++;
        } else if (c == ')') {
            numTypes--;
        }
    }

    // Step 2: Pop the types from the output frame stack
    for (int i = 0; i < numTypes; i++) {
        outputFrameStack.pop();
    }
}

