private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bound list with the first key
    List<Integer> upperBounds = new ArrayList<>();
    upperBounds.add(keys.get(0));

    // Iterate over the remaining keys
    for (int i = 1; i < keys.size(); i++) {
        // Get the current key and its upper bound
        K key = keys.get(i);
        int upperBound = upperBounds.get(i - 1);

        // Check if the current key is less than the upper bound
        if (key.compareTo(upperBound) < 0) {
            // If so, update the upper bound
            upperBounds.set(i, key);
        }
    }

    return upperBounds;
}

