    // Check if the AtmosphereResource is already registered
    if (this.atmosphereResourceListeners.contains(e)) {
        throw new IllegalStateException("AtmosphereResourceEventListener is already registered");
    }

    // Add the AtmosphereResourceEventListener to the list
    this.atmosphereResourceListeners.add(e);

    // Return the AtmosphereResource
    return this;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid relative path: " + relativePath);
    }

    // Check if the path is valid
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Invalid path: " + path);
    }

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is absolute
    if (relativePathComponents[0].isEmpty()) {
        // The relative path is absolute, so we can simply return it
        return relativePath;
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Check if the path is absolute
    if (pathComponents[0].isEmpty()) {
        // The path is absolute, so we need to remove the leading "/"
        pathComponents[0] = pathComponents[0].substring(1);
    }

    // Iterate over the relative path components and apply them to the path
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // The current directory, so do nothing
            continue;
        } else if (component.equals("..")) {
            // The parent directory, so remove the last component from the path
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else {
            // A regular directory, so add it to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // Join the path components back together
    return String.join("/", pathComponents);
}

